      "check_id": "CKV_AWS_54",
      "title": "S3 bucket public access block restrict_public_buckets is false",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket public access block has restrict_public_buckets set to false, potentially allowing public access to the bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket = aws_s3_bucket.api_docs.id\n  restrict_public_buckets = true\n}",
  "fix_summary": "Set restrict_public_buckets to true to restrict public access to the S3 bucket."
}
